def normalizar_observacoes(apps, schema_editor):
    for name in ('Pedido', 'ItemPedido'):
        apps.get_model('restaurante', name).objects.using(schema_editor.connection.alias).filter(observacao__isnull=True).update(observacao='')


def migrar_pedidos(apps, schema_editor):
    """Preserva pedidos antigos antes de remover mesa e a relação M2M de extras."""
    alias = schema_editor.connection.alias
    Pedido = apps.get_model('restaurante', 'Pedido')
    Sessao = apps.get_model('restaurante', 'SessaoMesa')
    Item = apps.get_model('restaurante', 'ItemPedido')
    Extra = apps.get_model('restaurante', 'ItemPedidoAdicional')
    Historico = apps.get_model('restaurante', 'HistoricoStatusPedido')
    for mesa_id in Pedido.objects.using(alias).values_list('mesa_id', flat=True).distinct():
        pedidos = Pedido.objects.using(alias).filter(mesa_id=mesa_id)
        ativa = pedidos.exclude(status__in=['ENTREGUE', 'CANCELADO']).exists()
        sessao = Sessao.objects.using(alias).create(
            mesa_id=mesa_id, ativa=ativa, fechada_em=None if ativa else timezone.now(),
        )
        for pedido in pedidos:
            novo = {'PENDENTE': 'RECEBIDO', 'EM_PREPARO': 'EM_PREPARACAO'}.get(pedido.status, pedido.status)
            Pedido.objects.using(alias).filter(pk=pedido.pk).update(sessao_id=sessao.pk, status=novo)
            Historico.objects.using(alias).create(pedido_id=pedido.pk, status_anterior='', status_novo=novo)
    for item in Item.objects.using(alias).prefetch_related('adicionais'):
        for adicional in item.adicionais.all():
            # O modelo legado não guardava o preço dos extras: fixa o valor disponível.
            Extra.objects.using(alias).create(item_pedido_id=item.pk, adicional_id=adicional.pk, preco=adicional.preco)


